package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.powermock.api.mockito.PowerMockito;
import org.powermock.core.classloader.annotations.PrepareForTest;
import org.powermock.modules.junit4.PowerMockRunner;
import static com.google.javascript.jscomp.CheckGlobalThis.GLOBAL_THIS;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(PowerMockRunner.class)
@PrepareForTest({CheckGlobalThis.class})
public class CheckGlobalThis_visit_TriageGen1Test {

    private CheckGlobalThis checkGlobalThis;

    @Mock
    private NodeTraversal t;

    @Mock
    private Node n;

    @Mock
    private Node parent;

    @Mock
    private Compiler compiler;

    @Mock
    private Compiler.AbstractReporter reporter;

    @Mock
    private Node errorNode;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        // We need to spy on checkGlobalThis to mock the private/protected shouldReportThis 
        // and to access the internal compiler field if it's not injectable.
        // Assuming compiler is a field in CheckGlobalThis.
        checkGlobalThis = PowerMockito.spy(new CheckGlobalThis());

        // Reflectively or via internal access set the compiler
        try {
            java.lang.reflect.Field compilerField = CheckGlobalThis.class.getDeclaredField("compiler");
            compilerField.setAccessible(true);
            compilerField.set(checkGlobalThis, compiler);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        when(compiler.report(any())).thenReturn(null);
    }

    @Test
    public void testVisit_ThisAndShouldReportThis_ReportsError() {
        // Setup: n.getType() == Token.THIS and shouldReportThis returns true
        when(n.getType()).thenReturn(Token.THIS);
        PowerMockito.doReturn(true).when(checkGlobalThis).shouldReportThis(n, parent);
        when(t.makeError(any(), any(), any())).thenReturn(errorNode);

        checkGlobalThis.visit(t, n, parent);

        verify(compiler).report(errorNode);
    }

    @Test
    public void testVisit_ThisAndNotShouldReportThis_NoErrorReport() {
        // Setup: n.getType() == Token.THIS but shouldReportThis returns false
        when(n.getType()).thenReturn(Token.THIS);
        PowerMockito.doReturn(false).when(checkGlobalThis).shouldReportThis(n, parent);

        checkGlobalThis.visit(t, n, parent);

        verify(compiler, org.mockito.Mockito.never()).report(any());
    }

    @Test
    public void testVisit_NotThis_NoErrorReport() {
        // Setup: n.getType() != Token.THIS
        when(n.getType()).thenReturn(Token.OTHER);

        checkGlobalThis.visit(t, n, parent);

        verify(compiler, org.mockito.Mockito.never()).report(any());
    }

    @Test
    public void testVisit_IsAssignLhsChild_SetsAssignLhsChildToNull() throws Exception {
        // Setup: n is the assignLhsChild
        java.lang.reflect.Field lhsField = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
        lhsField.setAccessible(true);
        lhsField.set(checkGlobalThis, n);

        // Ensure n is not THIS to isolate the second if block
        when(n.getType()).thenReturn(Token.OTHER);

        checkGlobalThis.visit(t, n, parent);

        assertNull("assignLhsChild should be null after visit", lhsField.get(checkGlobalThis));
    }

    @Test
    public void testVisit_IsNotAssignLhsChild_DoesNotChangeAssignLhsChild() throws Exception {
        // Setup: n is NOT the assignLhsChild
        Node otherNode = org.mockito.Mockito.mock(Node.class);
        java.lang.reflect.Field lhsField = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
        lhsField.setAccessible(true);
        lhsField.set(checkGlobalThis, n); // assignLhsChild is n

        when(n.getType()).thenReturn(Token.OTHER);

        checkGlobalThis.visit(t, otherNode, parent);

        // assignLhsChild should still be n
        assertNull(org.hamcrest.CoreMatchers.not(lhsField.get(checkGlobalThis) == n)); 
        // Correcting assertion:
        if (lhsField.get(checkGlobalThis) != n) {
            throw new AssertionError("assignLhsChild should not have been cleared");
        }
    }
}
